	OK       bool          `json:"ok"`
	Approval TrailApproval `json:"approval"`
}

// TrailApprovalsResponse is the response from GET .../:number/approvals.
type TrailApprovalsResponse struct {
	Approvals []TrailApproval `json:"approvals"`
}

